def min_cost_to_illuminate(n, m, k, blocked_positions, lamp_costs):
    blocked_set = set(blocked_positions)

    def can_cover_with_power(power):
        current_position = 0
        while current_position < n:
            if current_position in blocked_set:
                return False
            next_position = min(current_position + power, n)
            if next_position in blocked_set:
                return False
            current_position = next_position
        return True

    left, right = 1, n
    while left <= right:
        mid = (left + right) // 2
        if can_cover_with_power(mid):
            right = mid - 1
        else:
            left = mid + 1

    if left > k or not can_cover_with_power(left):
        return -1

    return lamp_costs[left - 1]

