def min_cost_to_illuminate(n, m, k, blocked_positions, lamp_costs):
    blocked_set = set(blocked_positions)
    i = 0
    while i < n:
        if i in blocked_set:
            return -1
        max_power = 0
        for power in range(1, k + 1):
            if i + power > n:
                break
            if i + power not in blocked_set:
                max_power = power
        if max_power == 0:
            return -1
        i += max_power
    return min(lamp_costs[:max_power])

