def min_cost_to_illuminate(n, m, k, blocked_positions, lamp_costs):
    blocked_set = set(blocked_positions)
    covered = [False] * n

    def cover_segment(start, end, power):
        if start >= n or end < 0:
            return False
        for i in range(max(0, start), min(n, end + 1)):
            if i not in blocked_set:
                covered[i] = True
        return True

    min_cost = float('inf')

    for power, cost in enumerate(lamp_costs, start=1):
        if all(covered):
            break
        current_cost = 0
        i = 0
        while i < n:
            if i in blocked_set:
                j = i + 1
                while j < n and j not in blocked_set:
                    j += 1
                if j == n:
                    break
                if cover_segment(i, j - 1, power):
                    current_cost += cost
                    i = j
                else:
                    break
            else:
                i += 1
        if all(covered):
            min_cost = min(min_cost, current_cost)

    return min_cost if min_cost != float('inf') else -1

